def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * (w // 3) for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = {}
            for r in range(br * 3, br * 3 + 3):
                for c in range(bc * 3, bc * 3 + 3):
                    v = grid[r][c]
                    if v not in (0, 5):
                        colors[v] = colors.get(v, 0) + 1
            if colors:
                out[br][bc] = max(colors, key=colors.get)
    return out
